import Link from 'next/link';
import Image from 'next/image';
import { getProductsByCollection } from '@/lib/shopify';

function formatPrice(amount: string, currency: string) {
  return new Intl.NumberFormat('en-GB', {
    style: 'currency',
    currency: currency,
  }).format(parseFloat(amount));
}

function calculateDiscount(price: number, comparePrice: number): number {
  if (!comparePrice || comparePrice <= price) return 0;
  return Math.round(((comparePrice - price) / comparePrice) * 100);
}

export default async function Bundles() {
  const products = await getProductsByCollection('huge-savings');

  return (
    <section className="py-16 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-3xl font-bold text-gray-900 text-center mb-4">
          Huge Savings
        </h2>
        <p className="text-gray-600 text-center mb-12 max-w-2xl mx-auto">
          Bundle your favorite products and save more
        </p>
        
        {products.length === 0 ? (
          <p className="text-center text-gray-500">
            No products found. Create a collection named &quot;huge-savings&quot; in your Shopify admin.
          </p>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6">
            {products.map(({ node }: { node: any }) => {
              const price = parseFloat(node.priceRange.minVariantPrice.amount);
              const comparePrice = node.compareAtPriceRange?.minVariantPrice?.amount 
                ? parseFloat(node.compareAtPriceRange.minVariantPrice.amount)
                : null;
              const discount = comparePrice ? calculateDiscount(price, comparePrice) : 0;
              const imageUrl = node.images.edges[0]?.node.url || '/product-1.jpg';

              return (
                <Link
                  key={node.id}
                  href={`/product/${node.handle}`}
                  className="group bg-white rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-shadow"
                >
                  <div className="aspect-square bg-gradient-to-br from-purple-100 to-blue-100 relative">
                    <Image
                      src={imageUrl}
                      alt={node.title}
                      fill
                      className="object-cover"
                    />
                  </div>
                  
                  <div className="p-4">
                    <h3 className="text-sm font-medium text-gray-900 group-hover:text-purple-600 transition-colors">
                      {node.title}
                    </h3>
                    
                    <div className="flex items-center gap-2 mt-2">
                      <span className="text-lg font-semibold text-gray-900">
                        {formatPrice(node.priceRange.minVariantPrice.amount, node.priceRange.minVariantPrice.currencyCode)}
                      </span>
                      {comparePrice && comparePrice > price && (
                        <span className="text-xs text-gray-500 line-through">
                          {formatPrice(comparePrice.toString(), node.priceRange.minVariantPrice.currencyCode)}
                        </span>
                      )}
                    </div>
                    
                    {discount > 0 && (
                      <span className="inline-block mt-2 bg-purple-100 text-purple-800 text-xs font-semibold px-2 py-1 rounded">
                        {discount}% Off
                      </span>
                    )}
                  </div>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </section>
  );
}
